import express from 'express';import dotenv from 'dotenv';dotenv.config();const app=express();app.use(express.json());const PORT=Number(process.env.GOOGLE_AGENT_GATEWAY_PORT||7192);app.get('/health',(_q,r)=>r.json({ok:true,service:'google-agent-gateway',enabled:process.env.ALLOW_CLOUD_CALLS==='1',project:process.env.GOOGLE_CLOUD_PROJECT||''}));app.post('/agent/job',(q,r)=>{if(process.env.ALLOW_CLOUD_CALLS!=='1')return r.status(409).json({ok:false,error:'ALLOW_CLOUD_CALLS=1 required'});r.json({ok:true,queued:true,request:q.body})});app.listen(PORT,'0.0.0.0',()=>console.log('google gateway',PORT));